const paths={sprout:'M12 22v-9M12 16C5 17 3 12 3 7c6-1 10 3 9 9Zm0-3C11 6 15 2 22 3c1 6-4 10-10 10Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm7 0a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87',funding:'M12 3v18m4-14H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6M7 3h10',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4',arrow:'M5 12h14m-5-5 5 5-5 5',external:'M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5','chevron-right':'m9 5 7 7-7 7','chevron-down':'m6 9 6 6 6-6',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4m-2-2h4',graduation:'m2 9 10-5 10 5-10 5L2 9Zm4 2v6c4 3 8 3 12 0v-6m4-2v7',message:'M21 11.5a8.4 8.4 0 0 1-9 8.5c-1.4 0-2.8-.3-4-.9L3 21l1.9-5C1 9.7 5 3 12 3a8.4 8.4 0 0 1 9 8.5ZM8 11h8',check:'m5 12 4 4L19 6',up:'m6 16 12-12m-8 0h8v8',refresh:'M3 10a9 9 0 0 1 15-6l3 3M21 3v4h-4M21 14a9 9 0 0 1-15 6l-3-3M3 21v-4h4',info:'M12 17v-5m0-4h.01M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0Z',clock:'M12 8v5l3 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',bookmark:'M6 3h12v19l-6-4-6 4V3Z',leaf:'M20 3c-15-2-19 8-13 14 6 6 16 2 13-14ZM4 21 16 9',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=(s)=>document.querySelector(s);
let persisted={};try{persisted=JSON.parse(localStorage.getItem('roots-demo-v1')||'{}')}catch{}
const data=window.ROOTS_DATA;
const state={view:'briefing',people:[...data.people,...(persisted.people||[])],events:[...data.events,...(persisted.events||[])],saved:persisted.saved||[],draft:persisted.draft||'',outreachEvent:persisted.outreachEvent||'e01',project:persisted.project||null,period:'October 2026',filter:'All people',search:'',fundFilter:'All opportunities',activity:persisted.activity||[]};
function persist(){window.RootsBridge?.sync();try{localStorage.setItem('roots-demo-v1',JSON.stringify({people:state.people.filter(p=>!data.people.some(d=>d.id===p.id)),events:state.events.filter(e=>!data.events.some(d=>d.id===e.id)),saved:state.saved,draft:state.draft,outreachEvent:state.outreachEvent,project:state.project,activity:state.activity.slice(0,15)}));return true}catch{toast('Browser storage is unavailable. Changes last for this visit.');return false}}
function logActivity(text){state.activity.unshift({text,time:'Just now',createdAt:new Date().toISOString()});persist()}
function avatar(p,cls=''){return `<span class="avatar ${esc(p.color)} ${cls}">${esc(p.initials)}</span>`}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)}
const navs=[['briefing','Overview','overview'],['people','People','users'],['opportunities','Opportunities','leaf'],['notices','Notices','message']];
const viewLabel=()=>navs.find(n=>n[0]===state.view)?.[1]||({chat:'Ask Roots',events:'Calendar'}[state.view]||'Overview');
function renderNav(){$('#navigation').innerHTML=navs.map(([id,label,i])=>`<a href="#${id}" aria-label="${label}" title="${label}" class="nav-item ${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');$('#page-label').textContent=viewLabel()}
function head(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function render(){renderNav();document.body.dataset.view=state.view;$('#main').innerHTML=({briefing:()=>window.RootsBriefing.render(),chat:()=>window.RootsChat.render(),people,opportunities:()=>window.RootsOpportunities.render(),notices:()=>window.RootsNotices.render(),events})[state.view]();document.title=`${viewLabel()} · Roots`;if(state.view==='chat')window.RootsChat.afterRender();}
function navigate(view){if(view==='funding')view='opportunities';if(view==='overview')view='briefing';if(view==='outreach')view='notices';if(![...navs.map(n=>n[0]),'events','chat'].includes(view))view='briefing';state.view=view;state.search='';state.filter='All people';window.scrollTo({top:0,behavior:'instant'});render()}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return}navigate(location.hash.slice(1))});
function eventRow(e){return `<button class="event-row" data-action="event" data-id="${esc(e.id)}"><span class="date-tile"><small>${esc(e.month)}</small><strong>${esc(e.day)}</strong></span><span class="event-info"><strong>${esc(e.title)}</strong><small>${esc(e.time)}</small><span class="event-spots">${icon('users')}${e.attendees} going · ${e.capacity-e.attendees} spots left</span></span></button>`}
function activityItems(){return `<div class="activity-item">${avatar(state.people[0])}<div><strong>Maya joined your community</strong><p>Interested in community gardening</p></div><span class="activity-time">2h ago</span></div><div class="activity-item"><span class="avatar sand">${icon('bookmark')}</span><div><strong>${state.activity[0]?esc(state.activity[0].text):'A new opportunity to grow'}</strong><p>${state.activity[0]?'Saved in this workspace':'College Corps added to your matches'}</p></div><span class="activity-time">${state.activity[0]?'Just now':'4h ago'}</span></div>`}
function people(){return window.RootsPeopleGroups?window.RootsPeopleGroups.render(peopleList):`${head('People','Find the people behind the possibilities.')}<div class="people-everyone-actions"><button class="button" data-action="add-person">${icon('plus')} Add volunteer</button></div>${peopleList()}`}
function peopleList(){const rows=state.people.filter(p=>(state.filter==='All people'||(state.filter==='First visit'?p.visits===1:p.status==='Active'))&&`${p.name} ${p.interests.join(' ')} ${p.email}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="list-toolbar"><label class="search-field">${icon('search')}<input id="people-search" type="search" placeholder="Search people or interests" aria-label="Search people or interests" value="${esc(state.search)}"></label><div class="filters" aria-label="Filter volunteers">${['All people','Active','First visit'].map(f=>`<button class="filter ${state.filter===f?'active':''}" aria-pressed="${state.filter===f}" data-action="people-filter" data-filter="${f}">${f}</button>`).join('')}</div></div><div id="people-results">${peopleTable(rows)}</div>`}
function peopleTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Volunteer</th><th>Interests</th><th>Availability</th><th>Hours</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="person-cell">${avatar(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.email)}</small></div></div></td><td><div class="tags">${p.interests.slice(0,2).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></td><td>${esc(window.RootsPeople.profileData(p).availability)}</td><td>${p.hours} h</td><td><span class="badge ${p.visits===1?'orange':'green'}">${esc(p.status)}</span></td><td><button class="icon-button" aria-label="View ${esc(p.name)}" data-action="person" data-id="${esc(p.id)}">${icon('chevron-right')}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${rows.length} of ${state.people.length} volunteers</span><span>Fictional profiles for this demo</span></div>`:`<div class="empty"><h3>No people found</h3><p>Try another name, interest, or filter.</p><button class="button" data-action="clear-search">Clear search</button></div>`}
function funding(){let ops=data.opportunities.filter(o=>state.fundFilter==='All opportunities'||(state.fundFilter==='Saved'?state.saved.includes(o.id):o.type===state.fundFilter));return `${head('Find your next opportunity.','Funded people, project support, and partnerships that fit your mission.')}<div class="list-toolbar"><div class="filters" aria-label="Filter opportunities">${['All opportunities','Fellowship','Grant','Partnership','Saved'].map(f=>`<button class="filter ${state.fundFilter===f?'active':''}" aria-pressed="${state.fundFilter===f}" data-action="fund-filter" data-filter="${f}">${f==='Saved'?`Saved (${state.saved.length})`:f}</button>`).join('')}</div><span class="tiny-label">${ops.length} opportunities</span></div><div class="help-banner">${icon('info')}Fellowships fund people and capacity. Grants fund eligible projects. Every lead needs a current eligibility check.</div>${ops.length?`<div class="opportunity-list">${ops.map(o=>`<article class="opportunity-card"><div class="rec-top"><span class="rec-icon">${icon(o.type==='Grant'?'leaf':'graduation')}</span><button class="icon-button save-button ${state.saved.includes(o.id)?'saved':''}" data-action="save" data-id="${o.id}" aria-label="${state.saved.includes(o.id)?'Unsave':'Save'} ${esc(o.title)}" aria-pressed="${state.saved.includes(o.id)}">${icon('bookmark')}</button></div><h3>${esc(o.title)}</h3><p>${esc(o.benefit)}</p><div class="card-bottom"><span class="badge ${o.fit==='High fit'?'green':'neutral'}">${esc(o.fit)} · ${o.type}</span><button class="button quiet" data-action="opportunity" data-id="${o.id}">Explore ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="empty"><h3>No saved opportunities yet</h3><p>Save a promising lead to come back to it here.</p><button class="button primary" data-action="fund-filter" data-filter="All opportunities">Explore opportunities</button></div>`}`}
function events(){return `${head('Make room for connection.','A shared calendar of small actions with a lasting impact.',`<button class="button primary" data-action="add-event">${icon('plus')} Create event</button>`)}<div class="section-title"><h2>Upcoming events</h2><span class="tiny-label">${state.events.length} ways to get involved</span></div><div class="events-grid">${state.events.map(e=>`<article class="event-card"><div class="event-card-top"><span class="date-tile"><small>${esc(e.month)}</small><strong>${e.day}</strong></span><span class="badge neutral">${esc(e.category)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="event-details"><span>${icon('clock')}${esc(e.weekday)} · ${esc(e.time)}</span><span>${icon('pin')}${esc(e.location)}</span></div><div><div class="capacity-track"><span style="width:${100*e.attendees/e.capacity}%"></span></div><div class="capacity-label"><span>${e.attendees} volunteers going</span><span>${e.capacity-e.attendees} spots open</span></div></div><button class="button quiet" data-action="event" data-id="${esc(e.id)}">View event ${icon('arrow')}</button></article>`).join('')}</div>`}
let dialogOpener=null;
function openDialog(kind,body){if(!$('#detail-dialog').open)dialogOpener=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-top"><span>${kind}</span><button class="icon-button" aria-label="Close panel" data-action="close">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;document.body.style.overflow='hidden';$('#detail-dialog').querySelector('[data-action="close"]').focus()}
function closeDialog(){$('#detail-dialog').close()}
$('#detail-dialog').addEventListener('close',()=>{document.body.style.overflow='';if(dialogOpener?.isConnected)dialogOpener.focus()});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)closeDialog()}});
function opportunity(id){window.RootsOpportunities.open(id)}
function outreach(eventId){
  const selectedId=eventId||state.outreachEvent,selected=state.events.find(event=>event.id===selectedId);
  if(!selected){toast('This event is no longer in your calendar. Open a current event before drafting an invitation.');return;}
  const category=String(selected.category||'').toLowerCase();
  const audience=state.people.filter(person=>person.visits===1&&person.interests.some(interest=>String(interest).toLowerCase()===category)).map(person=>person.id);
  state.outreachEvent=selected.id;
  window.RootsNotices.compose(null,null,audience,{eventId:selected.id});
}
function project(){openDialog('Project studio',`<span class="badge green">Built around your mission</span><h2 id="dialog-title">Start with what you have.</h2><p class="lead">Bring volunteer skills, your spaces, and a promising opportunity into a practical project outline.</p><form id="project-form"><div class="form-field"><label for="project-focus">What would you like to grow?</label><select id="project-focus"><option value="garden">A community learning garden</option><option value="compost">A community composting program</option><option value="native">A native habitat learning space</option></select></div><div class="form-field"><label for="project-goal">Your goal</label><textarea id="project-goal" style="min-height:100px" placeholder="e.g. Give local students a hands-on way to learn and volunteer" maxlength="1000"></textarea></div><button class="button primary wide" type="submit">${icon('sparkles')} Build example project plan</button></form><div id="project-result" class="project-result"></div><p class="source-note">A locally assembled example based on your choices, for staff review. No live AI or funding application is connected.</p>`);if(state.project){$('#project-focus').value=state.project.focus||'garden';$('#project-goal').value=state.project.goal||'';$('#project-form').requestSubmit()}}
function person(id){window.RootsPeople.open(id)}
function eventDetail(id){const e=state.events.find(x=>x.id===id);if(!e)return;openDialog('Community calendar',`<span class="badge green">${esc(e.category)}</span><h2 id="dialog-title">${esc(e.title)}</h2><p class="lead">${esc(e.description)}</p><div class="event-details"><span>${icon('calendar')}${esc(e.weekday)}, ${esc(e.month)} ${e.day}, 2026</span><span>${icon('clock')}${esc(e.time)}</span><span>${icon('pin')}${esc(e.location)}</span><span>${icon('users')}${e.attendees} going · ${e.capacity-e.attendees} open spots</span></div><section class="dialog-section"><h3>A good day to get involved</h3><p>Wear comfortable clothes and closed-toe shoes. Bring water and a little curiosity. Your shift lead will welcome you and walk you through the plan.</p></section><section class="dialog-section"><h3>Invite the right people</h3><p>A personal invitation can help a first-time volunteer find their next visit.</p></section><button class="button primary wide" data-action="outreach" data-event="${esc(e.id)}">Draft a volunteer invitation ${icon('arrow')}</button><p class="source-note">This event is fictional. No booking or message is sent from this demo.</p>`)}
function addPerson(){openDialog('Grow your community',`<h2 id="dialog-title">Add a volunteer</h2><p class="lead">Create a demo profile and see your community grow.</p><form id="person-form"><div class="form-field"><label for="person-name">Full name</label><input id="person-name" name="name" required maxlength="80" autocomplete="off" placeholder="e.g. Avery Green"></div><div class="form-field"><label for="person-email">Email</label><input id="person-email" name="email" type="email" required maxlength="120" autocomplete="off" placeholder="avery@example.com"></div><div class="form-field"><label for="person-interest">Main interest</label><select id="person-interest" name="interest"><option>Community gardening</option><option>Climate action</option><option>Composting</option><option>Native plants</option><option>Food recovery</option></select></div><div class="form-field"><label for="person-availability">Availability</label><select id="person-availability" name="availability"><option>Saturday mornings</option><option>Weekday afternoons</option><option>Weekday evenings</option><option>Weekend afternoons</option></select></div><label class="consent-row"><input type="checkbox" name="consent">SMS permission has been explicitly recorded for this demo profile.</label><button type="submit" class="button primary wide">Add volunteer ${icon('plus')}</button><p class="source-note">Use fictional information for this demonstration. Records are stored only in this browser.</p></form>`)}
function addEvent(){openDialog('Community calendar',`<h2 id="dialog-title">Make something happen.</h2><p class="lead">Add an upcoming volunteer event to your demo calendar.</p><form id="event-form"><div class="form-field"><label for="event-name">Event name</label><input id="event-name" name="title" required maxlength="100" placeholder="e.g. A morning in the garden"></div><div class="form-row"><div class="form-field"><label for="event-date">Date</label><input id="event-date" name="date" type="date" min="2026-10-25" max="2026-12-31" value="2026-11-14" required></div><div class="form-field"><label for="event-capacity">Volunteer spots</label><input id="event-capacity" name="capacity" type="number" min="1" max="250" value="15" required></div></div><div class="form-row"><div class="form-field"><label for="event-start">Starts</label><input id="event-start" name="start" type="time" value="09:00" required></div><div class="form-field"><label for="event-end">Ends</label><input id="event-end" name="end" type="time" value="12:00" required></div></div><div class="form-field"><label for="event-location">Location</label><input id="event-location" name="location" required maxlength="120" placeholder="e.g. Willow Community Garden"></div><div class="form-field"><label for="event-description">What will you do?</label><textarea id="event-description" name="description" required maxlength="600" style="min-height:100px" placeholder="Tell volunteers what to expect."></textarea></div><button class="button primary wide" type="submit">Create event ${icon('plus')}</button><p class="source-note">This creates a local demo event. No invitations are sent.</p></form>`)}
function toggleSave(id){if(state.saved.includes(id)){state.saved=state.saved.filter(x=>x!==id);persist();toast('Opportunity removed from saved')}else{state.saved.push(id);logActivity('An opportunity saved for your team');toast('Opportunity saved')}if(state.view==='funding')render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close')closeDialog();else if(a==='navigate')location.hash=b.dataset.view;else if(a==='opportunity')opportunity(b.dataset.id);else if(a==='outreach')outreach(b.dataset.event);else if(a==='project')project();else if(a==='person')person(b.dataset.id);else if(a==='event')eventDetail(b.dataset.id);else if(a==='save')toggleSave(b.dataset.id);else if(a==='save-dialog'){toggleSave(b.dataset.id);b.innerHTML=`${icon('bookmark')}${state.saved.includes(b.dataset.id)?'Saved to your opportunities':'Save opportunity'}`}else if(a==='people-filter'){state.filter=b.dataset.filter;render();$('.filter.active')?.focus()}else if(a==='fund-filter'){state.fundFilter=b.dataset.filter;render();$('.filter.active')?.focus()}else if(a==='clear-search'){state.search='';state.filter='All people';render();$('#people-search').focus()}else if(a==='add-person')addPerson();else if(a==='add-event')addEvent();else if(a==='retention')openDialog('Community snapshot',`<h2 id="dialog-title">A second visit matters.</h2><p class="lead">${state.period==='October 2026'?'42%':'34%'} of first-time visitors in this illustrative monthly cohort returned for another shift.</p><section class="dialog-section"><h3>Help the next visit happen</h3><p>A thank-you, an event that matches their interests, and an easy reply can make volunteering a habit.</p></section><button class="button primary wide" data-action="outreach">Plan a personal invitation ${icon('arrow')}</button><p class="source-note">The return rate is a fictional monthly cohort metric. It is not calculated from the all-time profile list.</p>`);else if(a==='activity')openDialog('Your workspace',`<h2 id="dialog-title">Around your community</h2><p class="lead">Small steps, adding up.</p><div class="activity-list">${state.activity.map(a=>`<div class="activity-item"><span class="avatar sage">${icon('check')}</span><div><strong>${esc(a.text)}</strong><p>${esc(a.time)} · Demo workspace</p></div></div>`).join('')}${activityItems()}</div>`);else if(a==='about')openDialog('About this workspace',`<span class="badge green">Illustrative demo</span><h2 id="dialog-title">Welcome to Greenfield Farm.</h2><p class="lead">A fictional workspace showing how Roots can connect volunteers, projects, and opportunities.</p><section class="dialog-section"><h3>Make yourself at home</h3><p>Explore people, save a promising opportunity, design an outreach draft, or add an event. Changes are saved in this browser and shared with the assistant when the local connection is running.</p></section><section class="dialog-section"><h3>Your team stays in control</h3><p>The connected assistant uses Gemini to read your demo records and prepare drafts. Telegram shares the local workspace. SMS and email delivery are not connected, and no outreach is sent.</p></section>`)});
document.addEventListener('input',e=>{if(e.target.id==='people-search'){state.search=e.target.value;const rows=state.people.filter(p=>(state.filter==='All people'||(state.filter==='First visit'?p.visits===1:p.status==='Active'))&&`${p.name} ${p.interests.join(' ')} ${p.email}`.toLowerCase().includes(state.search.toLowerCase()));$('#people-results').innerHTML=peopleTable(rows)}if(e.target.id==='draft-message')$('#message-preview').textContent=e.target.value.replaceAll('{first_name}',state.people.find(p=>p.visits===1&&p.consent)?.name.split(' ')[0]||'Maya')});
document.addEventListener('change',e=>{if(e.target.id==='period'){state.period=e.target.value;render();$('#period').focus()}if(e.target.id==='outreach-event'){const ev=state.events.find(x=>x.id===e.target.value);state.outreachEvent=ev.id;$('#draft-message').value=`Hi {first_name}, it was lovely having you at the garden! Would you like to join us for ${ev.title} on ${ev.month} ${ev.day}, ${ev.time}? Reply YES, NO, or suggest another day.`;$('#draft-message').dispatchEvent(new Event('input',{bubbles:true}))}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='outreach-form'){state.draft=$('#draft-message').value.trim();if(!state.draft)return;logActivity('An outreach draft ready for review');closeDialog();if(state.view==='overview')render();toast('Outreach draft saved. No messages sent.')}else if(e.target.id==='person-form'){const f=new FormData(e.target);const name=String(f.get('name')).trim(),email=String(f.get('email')).trim();if(!name){$('#person-name').setCustomValidity('Enter a name with at least one letter.');$('#person-name').reportValidity();return}if(state.people.some(p=>p.email.toLowerCase()===email.toLowerCase())){$('#person-email').setCustomValidity('This email is already in your community.');$('#person-email').reportValidity();return}state.people.push({id:`p-${Date.now()}`,name,email,initials:name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase(),color:'sage',interests:[f.get('interest')],availability:f.get('availability'),hours:0,visits:0,status:'Active',consent:f.has('consent')});logActivity(`${name} joined your community`);closeDialog();render();toast('Volunteer added to your demo community')}else if(e.target.id==='event-form'){const f=new FormData(e.target);if(f.get('end')<=f.get('start')){$('#event-end').setCustomValidity('End time must be after the start time.');$('#event-end').reportValidity();return}const d=new Date(`${f.get('date')}T12:00:00`);const time=t=>new Date(`2026-10-24T${t}`).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});state.events.push({id:`e-${Date.now()}`,title:String(f.get('title')).trim(),month:d.toLocaleDateString('en-US',{month:'short'}).toUpperCase(),day:d.getDate(),weekday:d.toLocaleDateString('en-US',{weekday:'long'}),time:`${time(f.get('start'))} – ${time(f.get('end'))}`,location:String(f.get('location')).trim(),description:String(f.get('description')).trim(),date:String(f.get('date')),category:'Community',attendees:0,capacity:Number(f.get('capacity'))});sortEvents();logActivity(`New event: ${f.get('title')}`);closeDialog();render();toast('Event added to your demo calendar')}else if(e.target.id==='project-form'){const focus=$('#project-focus').value;const plans={garden:{title:'A learning garden, grown together',activity:'Create four learning beds and host a weekly student gardening shift.',skills:'Gardening, environmental education, and community outreach',steps:['Confirm a staff supervisor and a campus partner.','Invite volunteers with gardening and mentoring interests.','Pilot four weekly shifts and collect participant feedback.']},compost:{title:'Less waste. More possibility.',activity:'Pilot a neighborhood compost hub and monthly hands-on workshops.',skills:'Composting, data analysis, and climate action',steps:['Check site suitability and local composting requirements.','Assign a trained lead and agree collection routines.','Track weekly material volume and workshop participation.']},native:{title:'A little habitat with a lasting impact',activity:'Transform a garden edge into a native-plant learning space.',skills:'Native plants, ecosystem restoration, and photography',steps:['Confirm site permissions and locally appropriate plants.','Schedule planting shifts with an experienced supervisor.','Document planting survival and run a community learning walk.']}};const p=plans[focus];state.project={...p,focus,goal:$('#project-goal').value.trim()};persist();$('#project-result').innerHTML=`<div class="success-panel"><strong>${icon('sprout')}${p.title}</strong>${p.activity}</div>${state.project.goal?`<section class="dialog-section"><h3>Your goal</h3><p>${esc(state.project.goal)}</p></section>`:''}<section class="dialog-section"><h3>Skills already in your community</h3><p>${p.skills}</p></section><section class="dialog-section"><h3>A practical starting plan</h3><ol class="step-list">${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><button class="button wide" data-action="opportunity" data-id="${focus==='compost'?'o02':'o01'}">Explore a potential partnership ${icon('arrow')}</button>`;$('#project-result').classList.add('visible');e.target.querySelector('button').innerHTML=`${icon('refresh')} Update example plan`;toast('Example project plan created')}});
document.addEventListener('input',e=>{if(e.target.matches('input'))e.target.setCustomValidity('')});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function invitation(ev){return `Hi {first_name}, it was lovely having you at the garden! Would you like to join us for ${ev.title} on ${ev.month} ${ev.day}, ${ev.time}? Reply YES, NO, or suggest another day.`}
function sortEvents(){const date=e=>e.date||`2026-${e.month==='OCT'?'10':e.month==='NOV'?'11':'12'}-${String(e.day).padStart(2,'0')}`;state.events.sort((a,b)=>date(a).localeCompare(date(b)))}
const extensionApi={getState:()=>state,data,head,icon,esc,avatar,render,openDialog,closeDialog,toast,persist,logActivity,showPerson:person,showOpportunity:opportunity,showEvent:eventDetail,draftMessage:id=>window.RootsNotices.compose(id)};
window.RootsOpportunities.configure(extensionApi);
window.RootsPeople.configure(extensionApi);
window.RootsPeopleGroups?.configure(extensionApi);
window.RootsNotices.configure(extensionApi);
window.RootsBridge.configure(extensionApi);
window.RootsChat.configure(extensionApi);
window.RootsBriefing.configure(extensionApi);
document.querySelector('.sidebar-toggle').addEventListener('click',()=>{const collapsed=document.body.classList.toggle('sidebar-collapsed');const button=document.querySelector('.sidebar-toggle');button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');try{localStorage.setItem('roots-sidebar-collapsed',String(collapsed));}catch{}});
try{if(localStorage.getItem('roots-sidebar-collapsed')==='true')document.querySelector('.sidebar-toggle').click();}catch{}
document.addEventListener('click',e=>{if(e.target.closest('[data-assistant-open]'))location.hash='chat'});
sortEvents();navigate(location.hash.slice(1)||'briefing');window.RootsBridge.init();
